"""Qualified fields are supplied hypotheses; scope/arrival assumptions are not empirical incidence."""
from decimal import Decimal as Q,ROUND_CEILING
q=lambda n:Q(str(n))
ceil=lambda n:int(q(n).to_integral_value(rounding=ROUND_CEILING))
def local_size(Eref):
 if not isinstance(Eref,int) or isinstance(Eref,bool) or Eref<=0:raise ValueError('Actual positive charter reference needed')
 return min(Eref,9 if Eref<=10000 else 15 if Eref<=100000 else 25)
def field(E,N,R,K,question=False):
 if any(not isinstance(n,int) or isinstance(n,bool) or n<0 for n in [E,N,R,K]) or E==0 or N==0:raise ValueError('Unsupported electoral bounds')
 threshold=ceil(q(E)/100) if question else min(ceil(q(E)/100),ceil(q(E)/(4*N)));lists=2*R//threshold;names=0 if question else min(2*N*lists,K)
 return {'E_call':E,'N_fixed':N,'R_cutoff':R,'threshold':threshold,'lists_or_committees_upper':lists,'nominee_entries_upper':names,'endorsement_acts_upper':2*R,'actual_independent_eligible_people':None}
def compute(cfg):
 national=field(cfg['E_call'],cfg['N'],cfg['R_cutoff'],cfg['K_nominees']);locals=[{'id':x['id'],'E_ref':x['E_ref'],**field(x['E_call'],local_size(x['E_ref']),x['R_cutoff'],x['K_nominees'])} for x in cfg['local_bodies']];questions=[{'id':x['id'],**field(x['E_call'],1,x['R_cutoff'],0,True)} for x in cfg['questions']];allfields=[national]+locals+questions;s=cfg['source_hours'];j=cfg['judicial'];info=cfg['information'];H=q(cfg['pay']['annual_task_hours']);day=q(s['task_hours_day']);R=cfg['R_cutoff'];localR=sum(x['R_cutoff'] for x in locals);questionR=sum(x['R_cutoff'] for x in questions);lists=sum(x['lists_or_committees_upper'] for x in allfields);nominees=sum(x['nominee_entries_upper'] for x in allfields);acts=sum(x['endorsement_acts_upper'] for x in allfields)
 baseline=q(acts)*q(s['old_endorsement_each'])+q(nominees)*q(s['old_nominee_each'])+q(lists)*q(s['list_each'])
 identity=q(cfg['matched_person_identity_count'])*q(s['identity_each']);nationalelig=q(R)*q(s['national_eligibility_each']);questionelig=Q(0) if cfg['matched_national_question_P_scope_hypothesis'] else q(questionR)*q(s['national_eligibility_each']);localelig=q(localR)*q(s['local_eligibility_each']);manifest=q(national['nominee_entries_upper'])*q(s['national_nominee_act_each'])+sum(q(x['nominee_entries_upper'])*q(s['local_nominee_act_each']) for x in locals)
 shared=identity+nationalelig+questionelig+localelig+q(acts)*q(s['endorsement_act_each'])+manifest+q(lists)*q(s['list_each']);sourceprofiles={}
 for name,hours in [('no_support_reuse',baseline),('matched_support_reuse',shared)]:
  n=ceil(hours/(q(s['available_final_task_days'])*day));sourceprofiles[name]={'task_hours':hours,'peak_distinct_people':n,'paid_role_equivalents':q(n)*q(s['source_paid_role_fraction']),'with_drill_task_hours':hours+q(n)*q(s['drill_hours_each']),'pay_quote_CU':q(n)*q(s['source_paid_role_fraction'])*q(cfg['pay']['professional']),'actual_source_compatibility_or_released_people':None}
 cases=sum(ceil(q(x['nominee_entries_upper'])*q(j['nominee_challenge_fraction']))+ceil(q(x['lists_or_committees_upper'])*q(j['list_or_committee_challenge_fraction'])) for x in allfields);sharedcases=ceil(q(cases)*q(j['opt_in_common_fraction']));unique=cases-sharedcases;families=min(sharedcases,j['common_families']);judicial={}
 for label,reuse in [('unshared',False),('opt_in_common',True)]:
  if not reuse:urgent=q(cases)*q(j['urgent_hours_each']);merits=q(cases)*q(j['merits_hours_each']);aidurgent=q(cases)*q(j['counsel_urgent_each']);aidmerits=q(cases)*q(j['counsel_merits_each'])
  else:
   urgent=q(unique)*q(j['urgent_hours_each'])+q(sharedcases)*q(j['individual_urgent_hours'])+q(families)*q(j['common_urgent_hours']);merits=q(unique)*q(j['merits_hours_each'])+q(sharedcases)*q(j['individual_merits_hours'])+q(families)*q(j['common_merits_hours']);aidurgent=q(unique)*q(j['counsel_urgent_each'])+q(sharedcases)*q(j['individual_counsel_urgent_hours'])+q(families)*q(j['common_counsel_urgent_hours']);aidmerits=q(unique)*q(j['counsel_merits_each'])+q(sharedcases)*q(j['individual_counsel_merits_hours'])+q(families)*q(j['common_counsel_merits_hours'])
  judicial[label]={'case_entries':cases,'opt_in_common_entries':sharedcases if reuse else 0,'assumed_common_families':families if reuse else 0,'urgent_judge_hours':urgent,'merits_judge_hours':merits,'urgent_counsel_hours':aidurgent,'merits_counsel_hours':aidmerits,'peak_judges':max(ceil(urgent/day),ceil(merits/(q(j['merits_available_task_days'])*day))),'peak_counsel':max(ceil(aidurgent/day),ceil(aidmerits/(q(j['merits_available_task_days'])*day))),'all_merits_immediately_due_judges':ceil(merits/day),'all_merits_immediately_due_counsel':ceil(aidmerits/day),'actual_common_issue_finding_consent_or_incidence':None,'actual_due_roster_or_timely_remedy':None}
 choice=sum(ceil(q(x['lists_or_committees_upper'])/q(info['rows_per_choice_page']))*x['E_call'] for x in allfields);guides=sum(ceil((q(x['lists_or_committees_upper'])*q(info['words_per_list'])+q(x['nominee_entries_upper'])*q(info['name_words_each']))/q(info['words_per_guide_page']))*x['E_call'] for x in allfields)
 requested=ceil(q(info['requested_guides_national'])*q(info['words_per_list'])/q(info['words_per_guide_page']))+ceil(q(info['requested_nominee_lists_national'])*2*cfg['N']*q(info['name_words_each'])/q(info['words_per_guide_page']));partial=q(cfg['E_call'])*requested
 for x in locals:partial+=q(x['E_call'])*(ceil(q(info['requested_guides_local'])*q(info['words_per_list'])/q(info['words_per_guide_page']))+ceil(q(info['requested_nominee_lists_local'])*2*x['N_fixed']*q(info['name_words_each'])/q(info['words_per_guide_page'])))
 for x in questions:partial+=q(x['E_call'])*ceil(q(info['requested_guides_question'])*q(info['words_per_list'])/q(info['words_per_guide_page']))
 helprequests=ceil(q(cfg['E_call'])*q(info['help_request_fraction']));helphours=q(helprequests)*q(info['help_hours_each']);helpers=ceil(helphours/(q(info['help_available_task_days'])*day));costfactor=q(info['access_factor'])*q(info['page_CU']);un=judicial['unshared'];src=sourceprofiles['matched_support_reuse'];clerks=max(ceil(q(cases)*q(j['clerk_urgent_hours_each'])/day),ceil(q(cases)*q(j['clerk_hours_each'])/(q(j['clerk_available_task_days'])*day)));trainingpeople=src['peak_distinct_people']+un['peak_judges']+un['peak_counsel']+helpers+clerks;trainhours=q(trainingpeople)*q(s['drill_hours_each'])/q(cfg['trainer']['group_people'])*(1+q(cfg['trainer']['prep_fraction']));trainers=0
 for _ in range(100):
  new=ceil((trainhours+q(trainers)*q(cfg['trainer']['own_learning_task_hours']))/H)
  if new==trainers:break
  trainers=new
 else:raise ValueError('Unbounded training fixedpoint')
 pay=src['pay_quote_CU']+q(un['peak_judges']+un['peak_counsel'])*q(j['paid_role_fraction_each'])*q(cfg['pay']['professional'])+q(clerks)*q(j['clerk_paid_role_fraction_each'])*q(cfg['pay']['frontline'])+q(helpers)*q(info['help_paid_role_fraction'])*q(cfg['pay']['frontline'])+q(trainers)*q(cfg['pay']['professional'])
 return {'national':national,'local':locals,'question':questions,'total_candidate_entries_not_distinct_persons':nominees,'total_lists_and_committees':lists,'total_endorsement_acts':acts,'source_profiles':sourceprofiles,'judicial_profiles':judicial,'paper':{'mandatory_choice_pages_hypothesis':choice,'all_requested_fullguide_pages':guides,'segmented_request_pages_hypothesis':partial,'fullrequest_including_choice_CU':q(choice+guides)*costfactor,'selected_request_hypothesis_including_choice_CU':q(choice+partial)*costfactor,'actual_voter_understanding_or_usability':None},'information_help':{'requests_hypothesis':helprequests,'task_hours':helphours,'peak_distinct_helpers':helpers,'annual_task_role_bound_without_peak':ceil(helphours/H),'actual_need_timing_or_available_people':None},'named_work_plan':{'source_people':src['peak_distinct_people'],'judges':un['peak_judges'],'counsel':un['peak_counsel'],'clerks':clerks,'clerk_paid_role_equivalents':q(clerks)*q(j['clerk_paid_role_fraction_each']),'clerk_all_work_immediately_due_people':ceil(q(cases)*q(j['clerk_hours_each'])/day),'information_helpers':helpers,'additional_drill_instructors':trainers,'instruction_hours_before_own_learning':trainhours,'gross_pay_quote_CU':pay,'actual_appointment_release_qualification_independence_or_source':None}}
